noncomputable def contaminate (P Q : Measure Ω) (ε : ℝ) : Measure Ω :=
  ENNReal.ofReal (1 - ε) • P + ENNReal.ofReal ε • Q

def grossErrorNbhd (P : Measure Ω) (ε : ℝ) : Set (Measure Ω) :=
  {R | ∃ Q : Measure Ω, IsProbabilityMeasure Q ∧ R = contaminate P Q ε}

def Resists (m : ℕ) : Prop :=
  ∃ M : ℝ, ∀ y : Fin n → ℝ, hammingDist x y ≤ m → |T y| ≤ M

noncomputable def breakdownCount : ℕ :=
  sSup {m | m ≤ n ∧ Resists T x m}

noncomputable def breakdownPoint : ℝ :=
  breakdownCount T x / n

variable {T x}

def HasInfluenceAt (T : Measure Ω → ℝ) (P : Measure Ω) (x : Ω) (v : ℝ) : Prop :=
  Tendsto (fun t : ℝ => (T (contaminate P (Measure.dirac x) t) - T P) / t)
    (𝓝[>] (0 : ℝ)) (𝓝 v)

